import java.util.*;
class TeachingGraphTraversal { static Map<String,List<String>> g(){Map<String,List<String>> m=new LinkedHashMap<String,List<String>>();m.put("A",Arrays.asList("B","C"));m.put("B",Arrays.asList("D"));m.put("C",Arrays.asList("D"));m.put("D",new ArrayList<String>());return m;} static void bfs(){Queue<String> q=new ArrayDeque<String>();Set<String> seen=new LinkedHashSet<String>();q.add("A");seen.add("A");while(!q.isEmpty()){String v=q.remove();System.out.print(v+" ");for(String w:g().get(v))if(seen.add(w))q.add(w);}System.out.println();} static void dfs(String v,Set<String> seen){seen.add(v);System.out.print(v+" ");for(String w:g().get(v))if(!seen.contains(w))dfs(w,seen);} }
